"""Generate database scripts from an app spec (Pandawa naming: APX_<APP>_*)."""
import core_sql

AUDIT_COLS = ["created_by", "created_on", "updated_by", "updated_on"]


def q(v):
    return "'" + str(v).replace("'", "''") + "'"


def header(app, script, purpose, date):
    return ("-" * 80 + "\n-- Script : %s\n-- Author : %s\n-- Date   : %s\n-- Purpose: %s\n"
            "-- Note   : GENERATED by pandawa-apexlang generator dari app.yaml. Jangan edit manual.\n"
            % (script, app.author, date, purpose) + "-" * 80 + "\n\n")


def col_default(c):
    if c.default is None:
        return None
    if c.type in ("number", "int", "money", "qty", "pct"):
        return str(c.default)
    if c.type == "date" and str(c.default).lower() in ("sysdate", "trunc(sysdate)"):
        return str(c.default).lower()
    return q(c.default)


def entity_table(app, e):
    lines = ["%s number generated by default on null as identity" % e.pk.lower()]
    d = e.document
    if d:
        lines.append("%s varchar2(30)" % d.number.lower())
    checks, uniques = [], []
    for c in e.columns:
        if c.virtual:
            lines.append("%s %s generated always as (%s) virtual" % (c.name.lower(), "number" if c.sql_type.startswith("number") else c.sql_type, c.virtual))
            continue
        s = "%s %s" % (c.name.lower(), c.sql_type)
        dv = col_default(c)
        if dv is not None:
            s += " default %s" % dv
        if c.required:
            s += " not null"
        lines.append(s)
        if c.type == "yn":
            checks.append("%s in ('Y', 'N')" % c.name.lower())
        if c.type == "enum":
            checks.append("%s in (%s)" % (c.name.lower(), ", ".join(q(k) for k in c.values)))
        if c.min is not None:
            checks.append("%s >= %s" % (c.name.lower(), c.min))
        if c.max is not None:
            checks.append("%s <= %s" % (c.name.lower(), c.max))
        if c.unique:
            uniques.append(c.name.lower())
    if d:
        lines.append("status varchar2(20) default 'DRAFT' not null")
        checks.append("status in (%s)" % ", ".join(q(s) for s in d.statuses))
    lines += ["created_by varchar2(255)", "created_on date", "updated_by varchar2(255)", "updated_on date"]
    cons = ["constraint %s_pk primary key (%s)" % (e.table, e.pk.lower())]
    n = 1
    if d:
        cons.append("constraint %s_u%d unique (%s)" % (e.table, n, d.number.lower()))
        n += 1
    for u in uniques:
        cons.append("constraint %s_u%d unique (%s)" % (e.table, n, u))
        n += 1
    for i, ck in enumerate(checks, 1):
        cons.append("constraint %s_ck%d check (%s)" % (e.table, i, ck))
    body = "\n  ,".join(lines + cons)
    return "create table %s (\n   %s\n);\n" % (e.table, body)


def entity_fks(app, e):
    out = []
    n = 1
    for c in e.columns:
        if c.type != "ref":
            continue
        r = app.entity(c.ref)
        on_del = " on delete cascade" if (c.on_delete == "cascade" or (e.parent and e.parent["column"] == c.name)) else ""
        out.append("alter table %s add constraint %s_fk%d foreign key (%s) references %s (%s)%s;"
                   % (e.table, e.table, n, c.name.lower(), r.table, r.pk.lower(), on_del))
        out.append("create index %s_n%d on %s (%s);" % (e.table, n, e.table, c.name.lower()))
        n += 1
    return "\n".join(out) + ("\n" if out else "")


def entity_trigger(app, e):
    p = app.prefix
    d = e.document
    events = "insert or update"
    if e.immutable or e.parent:
        events += " or delete"
    decl, body = [], []
    if e.immutable:
        body.append("""   if (updating or deleting) and not %s_approval_pkg.bypass then
      raise_application_error(-20120, '%s yang sudah tersimpan tidak dapat diubah atau dihapus. Buat transaksi koreksi.');
   end if;""" % (p, e.label.replace("'", "''")))
    if e.parent:
        pe = app.entity(e.parent["entity"])
        col = e.parent["column"].lower()
        decl.append("   l_parent_status varchar2(30);")
        decl.append("   e_mutating      exception;")
        decl.append("   pragma exception_init(e_mutating, -4091);")
        allowed = ", ".join(q(s) for s in e.parent["lock_unless"])
        body.append("""   begin
      select status
        into l_parent_status
        from %s
       where %s = coalesce(:new.%s, :old.%s);
   exception
      when e_mutating then
         return; -- delete cascade dari %s
   end;
   if not %s_approval_pkg.bypass and l_parent_status not in (%s) then
      raise_application_error(-20121, '%s tidak dapat diubah karena %s berstatus ' || l_parent_status || '.');
   end if;""" % (pe.table, pe.pk.lower(), col, col, pe.table, p, allowed,
                 e.label.replace("'", "''"), pe.label.replace("'", "''")))
    if "delete" in events:
        body.append("   if deleting then\n      return;\n   end if;")
    for c in e.columns:
        if c.type == "code" and not c.virtual:
            body.append("   :new.%s := upper(:new.%s);" % (c.name.lower(), c.name.lower()))
    if d:
        ops = ", ".join(q(s) for s in d.operational)
        restore = "\n".join("         :new.%s := :old.%s;" % (c.lower(), c.lower()) for c in d.lock)
        lbl = e.label.replace("'", "''")
        no = d.number.lower()
        body.append("""   if inserting then
      if not %(p)s_approval_pkg.bypass then
         :new.status := 'DRAFT';
      end if;
      if :new.%(no)s is null then
         :new.%(no)s := %(p)s_doc_pkg.next_no('%(type)s');
      end if;
   elsif not %(p)s_approval_pkg.bypass then
      if :old.status = 'SUBMITTED' then
         raise_application_error(-20110, '%(lbl)s ' || :old.%(no)s || ' sedang menunggu approval dan tidak dapat diubah.');
      end if;
      if :old.status in ('CANCELLED'%(closed)s) then
         raise_application_error(-20111, '%(lbl)s ' || :old.%(no)s || ' sudah ' || :old.status || '.');
      end if;
      if :new.status <> :old.status
         and not (%(ops_ok)s)
      then
         raise_application_error(-20112, 'Perubahan status ' || :old.status || ' -> ' || :new.status || ' tidak diizinkan. Gunakan Submit for Approval.');
      end if;%(restore)s
   end if;""" % {
            "p": p, "no": no, "type": d.type, "lbl": lbl,
            "closed": ", 'CLOSED'" if "CLOSED" in d.operational else "",
            "ops_ok": (":old.status in ('APPROVED', %s) and :new.status in (%s)" % (ops, ops)) if d.operational
            else ":new.status = 'CANCELLED' and :old.status in ('DRAFT', 'REJECTED')",
            "restore": ("\n      -- kolom terkunci setelah approval (BR change management)\n"
                        "      if :old.status not in ('DRAFT', 'REJECTED') then\n%s\n      end if;" % restore) if restore else "",
        })
    body.append("""   if inserting then
      :new.created_by := %s_sec_pkg.app_user;
      :new.created_on := sysdate;
   end if;
   :new.updated_by := %s_sec_pkg.app_user;
   :new.updated_on := sysdate;""" % (p, p))
    return ("create or replace trigger %s_trg\nbefore %s on %s\nfor each row\n%sbegin\n%s\nend;\n/\n"
            % (e.table, events, e.table, ("declare\n" + "\n".join(decl) + "\n") if decl else "", "\n".join(body)))


def entity_view_columns(app, e):
    """(sql_expr, alias) for the list view, in order."""
    cols = [("t.%s" % e.pk.lower(), e.pk)]
    if e.document:
        cols.append(("t.%s" % e.document.number.lower(), e.document.number))
    for c in e.columns:
        cols.append(("t.%s" % c.name.lower(), c.name))
        if c.type == "ref":
            r = app.entity(c.ref)
            cols.append(("(select %s from %s r where r.%s = t.%s)" % (r.display, r.table, r.pk.lower(), c.name.lower()),
                         c.name + "_DSP"))
    if e.document:
        cols.append(("t.status", "STATUS"))
    cols += [("t.%s" % a, a.upper()) for a in AUDIT_COLS]
    return cols


def entity_view(app, e):
    cols = entity_view_columns(app, e)
    sel = "\n      ,".join("%s %s" % (x, a.lower()) if not x.endswith("." + a.lower()) else x for x, a in cols)
    return "create or replace force view %s_v as\nselect %s\n  from %s t;\n" % (e.table, sel, e.table)


def dashboard_views(app):
    out = []
    dash = app.dashboard
    kpis = dash.get("kpis", [])
    if kpis:
        sel = "\n      ,".join("(%s) kpi_%d" % (k["sql"].strip().rstrip(";"), i + 1) for i, k in enumerate(kpis))
        out.append("create or replace force view %s_dash_kpi_v as\nselect %s\n  from dual;\n" % (app.prefix, sel))
    for i, ch in enumerate(dash.get("charts", []), 1):
        for j, s in enumerate(ch.get("series", []), 1):
            out.append("create or replace force view %s_dash_c%d_s%d_v as\n%s;\n" % (app.prefix, i, j, s["sql"].strip().rstrip(";")))
    return "\n".join(out)


def config_seed(app):
    p = app.prefix
    out = []
    for code, name in app.roles.items():
        out.append("""merge into %s_roles t
using (select %s role_code, %s role_name from dual) s
   on (t.role_code = s.role_code)
 when matched then update set t.role_name = s.role_name
 when not matched then insert (role_code, role_name) values (s.role_code, s.role_name);""" % (p, q(code), q(name)))
    for e in app.documents:
        d = e.document
        vals = {
            "doc_type": q(d.type), "doc_name": q(d.name), "prefix": q(d.prefix), "table_name": q(e.table.upper()),
            "pk_column": q(e.pk), "number_column": q(d.number), "status_column": "'STATUS'",
            "amount_expr": q(d.amount) if d.amount else "null", "validate_proc": q(d.validate) if d.validate else "null",
            "approver1_role": q(d.approver1.upper()) if d.approver1 else "null",
            "approver2_role": q(d.approver2.upper()) if d.approver2 else "null",
            "level2_limit": str(d.level2_limit),
        }
        keys = list(vals)
        out.append("merge into %s_doc_types t\nusing (select %s from dual) s\n   on (t.doc_type = s.doc_type)\n"
                   " when matched then update set %s\n when not matched then insert (%s) values (%s);"
                   % (p, ", ".join("%s %s" % (v, k) for k, v in vals.items()),
                      ", ".join("t.%s = s.%s" % (k, k) for k in keys if k not in ("doc_type", "prefix", "approver1_role", "approver2_role", "level2_limit")),
                      ", ".join(keys), ", ".join("s.%s" % k for k in keys)))
    out.append("commit;")
    return "\n\n".join(out) + "\n"


def deinstall(app):
    pat = app.prefix.upper().replace("_", "\\_") + "\\_%"
    return """-- Hapus SEMUA objek dengan prefix %(P)s_ (termasuk custom SQL). HANYA untuk sandbox.
begin
   for r in (select object_type
                   ,object_name
               from user_objects
              where object_name like '%(pat)s' escape '\\'
                and object_type in ('VIEW', 'TRIGGER', 'PACKAGE', 'PROCEDURE', 'FUNCTION', 'TABLE', 'SEQUENCE', 'TYPE')
              order by decode(object_type, 'VIEW', 1, 'TRIGGER', 2, 'PACKAGE', 3, 'PROCEDURE', 4, 'FUNCTION', 5, 'TABLE', 6, 7))
   loop
      begin
         execute immediate 'drop ' || r.object_type || ' ' || dbms_assert.simple_sql_name(r.object_name)
                           || case r.object_type when 'TABLE' then ' cascade constraints purge' end;
      exception
         when others then
            if sqlcode not in (-4043, -942) then -- sudah terhapus (mis. tabel ikut terhapus)
               raise;
            end if;
      end;
   end loop;
end;
/
""" % {"P": app.prefix.upper(), "pat": pat}


def users_script(app):
    p = app.prefix
    calls = []
    for u in app.users:
        roles = ",".join(u.get("roles", []))
        calls.append("   add_user(%-22s %-28s %s);" % (q(u["username"].upper()) + ",", (q(roles) if roles else "null") + ",", q(u.get("name", u["username"]))))
    return """%(hdr)sset serveroutput on

-- Jalankan sebagai workspace administrator: SQL Workshop > SQL Scripts > Upload > Run > View Results.
-- c_password null = password acak per user (dicetak sekali). Isi untuk password sama semua user.
-- JANGAN commit password ke repository. Aman dijalankan ulang (user yang ada tidak diubah).
declare
   c_password     constant varchar2(100) := null;
   c_email_domain constant varchar2(100) := 'example.com';
   c_workspace    constant varchar2(100) := null;  -- isi bila dijalankan via SQLcl
   c_extra_admin  constant varchar2(255) := null;  -- akun workspace lain yang juga dijadikan ADMIN
   -- Akun yang menjalankan script ini (developer di SQL Workshop) otomatis didaftarkan sebagai ADMIN,
   -- supaya tidak terkunci begitu mode bootstrap berakhir (ADMIN pertama terdaftar).
   l_runner       varchar2(255) := upper(sys_context('APEX$SESSION', 'APP_USER'));

   procedure add_user (
      p_user       in varchar2
     ,p_roles      in varchar2
     ,p_first_name in varchar2
   )
   is
      l_user   varchar2(255) := upper(p_user);
      l_pwd    varchar2(100);
      l_exists number;
   begin
      select count(*)
        into l_exists
        from apex_workspace_apex_users
       where user_name = l_user;

      if l_exists = 0 then
         l_pwd := coalesce(c_password, 'Px' || dbms_random.string('x', 8) || '#' || trunc(dbms_random.value(10, 99)));
         apex_util.create_user(
            p_user_name                    => l_user
           ,p_first_name                   => p_first_name
           ,p_last_name                    => '%(code)s'
           ,p_email_address                => lower(l_user) || '@' || c_email_domain
           ,p_web_password                 => l_pwd
           ,p_change_password_on_first_use => 'N');
         dbms_output.put_line(rpad(l_user, 20) || ' dibuat      password: ' || l_pwd);
      else
         dbms_output.put_line(rpad(l_user, 20) || ' sudah ada   (password tidak diubah)');
      end if;

      if p_roles is not null then
         for r in (select trim(column_value) role_code from table(apex_string.split(p_roles, ',')))
         loop
            merge into %(p)s_user_roles t
            using (select l_user username, upper(r.role_code) role_code from dual) s
               on (t.username = s.username and t.role_code = s.role_code)
             when not matched then
                  insert (username, role_code) values (s.username, s.role_code);
            dbms_output.put_line(rpad(' ', 20) || ' role: ' || upper(r.role_code));
         end loop;
      end if;
   end add_user;
begin
   if c_workspace is not null then
      apex_util.set_workspace(p_workspace => c_workspace);
   end if;

%(calls)s

   for r in (select upper(column_value) username
               from table(apex_t_varchar2(l_runner, c_extra_admin))
              where column_value is not null
                and upper(column_value) <> 'NOBODY')
   loop
      merge into %(p)s_user_roles t
      using (select r.username username, 'ADMIN' role_code from dual) s
         on (t.username = s.username and t.role_code = s.role_code)
       when not matched then
            insert (username, role_code) values (s.username, s.role_code);
      dbms_output.put_line(rpad(r.username, 20) || ' role: ADMIN (akun yang sudah ada / yang menjalankan script)');
   end loop;

   commit;
end;
/
""" % {"hdr": header(app, "create_users.sql", "Buat akun workspace APEX + daftarkan role %s" % app.code, app.date),
       "code": app.code, "p": p, "calls": "\n".join(calls) or "   null; -- tidak ada users: di app.yaml"}


def remove_users_script(app):
    names = ", ".join(q(u["username"].upper()) for u in app.users) or "null"
    return """set serveroutput on

-- Hapus akun workspace yang dibuat create_users.sql beserta role-nya. HANYA untuk sandbox.
declare
   c_workspace constant varchar2(100) := null;
   l_users     apex_t_varchar2 := apex_t_varchar2(%s);
   l_exists    number;
begin
   if c_workspace is not null then
      apex_util.set_workspace(p_workspace => c_workspace);
   end if;
   for i in 1 .. l_users.count
   loop
      continue when l_users(i) is null;
      delete from %s_user_roles where username = l_users(i);
      select count(*) into l_exists from apex_workspace_apex_users where user_name = l_users(i);
      if l_exists > 0 then
         apex_util.remove_user(p_user_name => l_users(i));
         dbms_output.put_line(rpad(l_users(i), 20) || ' dihapus');
      end if;
   end loop;
   commit;
end;
/
""" % (names, app.prefix)


def generate(app):
    """Return {relative_path: content} for database/generated/*."""
    date = app.date
    files = {}
    files["01_core_tables.sql"] = core_sql.render(core_sql.CORE_TABLES, app, date)
    files["02_entity_tables.sql"] = header(app, "02_entity_tables.sql", "Tabel entitas %s" % app.code, date) + \
        "\n".join(entity_table(app, e) for e in app.entities) + "\n" + \
        "-- foreign keys & index\n" + "".join(entity_fks(app, e) for e in app.entities)
    files["03_core_packages.sql"] = core_sql.render(core_sql.CORE_PACKAGES, app, date)
    files["04_triggers.sql"] = header(app, "04_triggers.sql", "Trigger audit, penomoran, guard status", date) + \
        core_sql.render(core_sql.CORE_TRIGGERS, app, date) + "\n" + "\n".join(entity_trigger(app, e) for e in app.entities)
    files["05_views.sql"] = header(app, "05_views.sql", "View untuk region APEX (MVC: query di view)", date) + \
        core_sql.render(core_sql.CORE_VIEWS, app, date) + "\n" + "\n".join(entity_view(app, e) for e in app.entities) + \
        "\n" + dashboard_views(app)
    files["06_config_seed.sql"] = header(app, "06_config_seed.sql", "Role & jenis dokumen (idempotent)", date) + config_seed(app)
    files["99_deinstall.sql"] = header(app, "99_deinstall.sql", "Deinstall semua objek %s_" % app.prefix.upper(), date) + deinstall(app)
    return files


def install_script(app, files, read_rel):
    """Single script for SQL Workshop > SQL Scripts: generated + custom + config + seed."""
    parts = ["-- %s - install gabungan (GENERATED). Jalankan di SQL Workshop > SQL Scripts atau SQLcl.\n" % app.name]
    for name in ["01_core_tables.sql", "02_entity_tables.sql", "03_core_packages.sql", "04_triggers.sql", "05_views.sql"]:
        parts.append("\n-- >>> generated/%s\n%s" % (name, files[name]))
    for f in app.custom_sql:
        parts.append("\n-- >>> %s\n%s" % (f, read_rel(f)))
    parts.append("\n-- >>> generated/06_config_seed.sql\n%s" % files["06_config_seed.sql"])
    for f in app.seed_sql:
        parts.append("\n-- >>> %s\n%s" % (f, read_rel(f)))
    return "".join(parts)
